 "🤖 Hi! I'm your AI Assistant. Ask me anything, like ChatGPT: how to use this system, your own data, general questions, writing, translation or calculations. Attach (📎) or snap (📷) a photo, PDF, Word, Excel or other file and ask about it. Turn on 🌐 to search the web. Try one of these:": "🤖 হ্যালো! আমি আপনার এআই সহকারী। ChatGPT-এর মতো যেকোনো কিছু জিজ্ঞাসা করুন: এই সিস্টেম ব্যবহার, আপনার নিজের ডেটা, সাধারণ প্রশ্ন, লেখা, অনুবাদ বা হিসাব। ছবি, PDF, Word, Excel বা অন্য ফাইল সংযুক্ত (📎) করুন বা তুলুন (📷) এবং সে সম্পর্কে জিজ্ঞাসা করুন। ওয়েবে খুঁজতে 🌐 চালু করুন। এগুলোর একটি চেষ্টা করুন:",
