 "1. Choose the event(s), or choose the recipes and their pax · 2. The menu gives the ingredients and quantities (from the recipes and the pax) · 3. Choose the supplier item of each ingredient, at the latest price of that supplier · 4. One purchase order is made for each supplier.": "1. ইভেন্ট বেছে নিন, অথবা রেসিপি ও তাদের পাক্স বেছে নিন · 2. মেনু থেকে (রেসিপি ও পাক্স অনুযায়ী) উপকরণ ও পরিমাণ পাওয়া যায় · 3. প্রতিটি উপকরণের জন্য সরবরাহকারীর আইটেম বেছে নিন, ওই সরবরাহকারীর সর্বশেষ দামে · 4. প্রতিটি সরবরাহকারীর জন্য একটি ক্রয় আদেশ তৈরি হয়।",
