 "One block for each day of the event (1 day, or 3-5 days for a conference). Use \"Add next day\" to copy the previous day.": "ইভেন্টের প্রতিটি দিনের জন্য একটি ব্লক (1 দিন, বা সম্মেলনের জন্য 3-5 দিন)। আগের দিনের কপি করতে “পরের দিন যোগ করুন” ব্যবহার করুন।",
 "One event and one quotation, with a block for each day: date, set-up and event time, meal and service type, menu, price and pax.": "একটি ইভেন্ট ও একটি কোটেশন, প্রতিটি দিনের জন্য একটি ব্লকসহ: তারিখ, সেট-আপ ও ইভেন্টের সময়, খাবার ও সার্ভিসের ধরন, মেনু, দাম ও pax।",
 "One name can work in several companies: a staff record is created in each ticked company, and the list shows the person once.": "একটি নাম একাধিক কোম্পানিতে কাজ করতে পারে: টিক দেওয়া প্রতিটি কোম্পানিতে স্টাফ রেকর্ড তৈরি হয়, এবং তালিকায় ব্যক্তিকে একবারই দেখানো হয়।",
 "One of the dates is not valid, so the list is not filtered.": "একটি তারিখ সঠিক নয়, তাই তালিকা ফিল্টার করা হয়নি।",
 "One of the fields is too long.": "একটি ফিল্ড অতিরিক্ত দীর্ঘ।",
 "One of the things I can do with a photo: attach (📎) or take (📷) a photo of a printed or handwritten menu and send it without a question. I read the dishes, ask for the pax only if it is not on the menu, and work out the ingredients from your approved recipes.": "ছবি দিয়ে আমি যা করতে পারি তার একটি: ছাপা বা হাতে লেখা মেনুর ছবি সংযুক্ত (📎) বা তুলুন (📷) এবং প্রশ্ন ছাড়াই পাঠান। আমি খাবারগুলো পড়ি, মেনুতে না থাকলেই কেবল পাক্স জিজ্ঞাসা করি এবং আপনার অনুমোদিত রেসিপি থেকে উপকরণ হিসাব করি।",
