 "This report contains bank details and is only available to Finance / Admin users of the company.": "এই রিপোর্টে ব্যাংকের তথ্য আছে এবং এটি শুধু কোম্পানির ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা দেখতে পারেন।",
 "This request has already been decided.": "এই অনুরোধের ওপর ইতিমধ্যে সিদ্ধান্ত নেওয়া হয়েছে।",
 "This request has already been reviewed.": "এই অনুরোধ আগেই পর্যালোচনা করা হয়েছে।",
