 "This transaction reference is already recorded against the same invoice (duplicate payment entry).": "এই লেনদেন রেফারেন্স একই ইনভয়েসের বিপরীতে ইতিমধ্যে রেকর্ড করা আছে (ডুপ্লিকেট পেমেন্ট এন্ট্রি)।",
